<div class="table-wrap"><table><thead><tr><th>No. tiket</th><th>Pelapor</th><th>Jenis</th><th>Teknisi</th><th>Status</th><th>Dibuat</th></tr></thead><tbody><?php if(!$tickets): ?><tr><td colspan="6" class="empty">Belum ada tiket.</td></tr><?php endif; foreach($tickets as $t): ?><tr class="click" onclick="location.href='<?= site_url('tickets/'.$t->id) ?>'"><td><b><?= html_escape($t->no_tiket) ?></b></td><td><?= html_escape($t->nama_pelapor) ?><small><?= html_escape($t->nama_unit) ?></small></td><td><?= html_escape($t->nama_jenis ?: $t->jenis_lainnya) ?></td><td><?= html_escape($t->teknisi ?: '—') ?></td><td><?= status_badge($t->nama_status,$t->color_code) ?></td><td><?= date('d M Y, H:i',strtotime($t->created_at)) ?></td></tr><?php endforeach; ?></tbody></table></div>
